# -*- coding: utf-8 -*-
"""docs/13-14-技术方案与数据模型-讲懂版.docx —— 13/14 两张 ticket 的准备材料。

读者是「不了解技术、不了解数据模型」的中文非开发者，不是工程师。
所以：不按工程分类，按「你在哪儿遇到它」分类；每个术语第一次出现用一句人话解释；
不替他做决定，末尾只列选项和代价。

事实来源（全部核对过代码）：
- src/types.ts         GameState 39 个字段（逐个数过：21 + 10 + 8）
- src/core/save.ts     存档：只清 temp，其余跟存档走；版本号进键名
- src/core/state.ts    newGame 默认值；src/config.ts start.{stamina,coachTrust,rankPoints}
- src/core/match.ts    injuryBench=2 不能上场、injuryMax=3 赛季报销（config.ts:163-165）
- src/config.ts        startThreshold=60 才首发、storageKey='lpl-career-proto'、version=3
- vite.config.ts + package.json   单文件打包、target es2020
- src/ui/main.ts       界面上到底有哪些字（段位/名次/信任/伤病/体力/金钱/荣誉/收支/商店）
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "13-14-技术方案与数据模型-讲懂版.docx")


def main():
    doc = k.new_doc("13/14 讲懂版 / 给非工程读者 · v0.2 · 2026-11-05")
    k.title(
        doc,
        "技术方案与数据模型 · 讲懂版",
        "不是工程文档 · 每个术语第一次出现都用一句人话解释 · v0.2 · 2026-11-05",
    )

    k.note(
        doc,
        "这份文档**不替你做决定**。它只干两件事：把 3.1 / 3.2 里的工程话翻成人话；"
        "末尾把要你拍板的问题列出来，每个选项都写清代价。",
    )
    k.note(
        doc,
        "事实来源：src/types.ts（39 个字段）、src/core/save.ts（存档）、"
        "src/config.ts + src/core/state.ts（默认值与阈值）、vite.config.ts + package.json（打包）、"
        "src/ui/main.ts（界面上有什么）。工程版仍以 docs/3.1-技术方案.docx 与 docs/3.2-数据模型.docx 为准，"
        "本文只负责解释，不替代它们。",
    )

    # ---------------- 一 ----------------
    k.h1(doc, "一", "这台技术栈到底在干什么")
    k.para(
        doc,
        "一句话：**没有服务器、没有账号、没有安装包**。玩家在手机浏览器里打开一个 index.html，"
        "这个文件里同时装着三样东西——长什么样的界面、点一下会发生什么的规则、以及事件和队伍的文本。"
        "玩到一半关掉，进度存在浏览器自己的小抽屉里。",
    )
    k.para(
        doc,
        "这不是技术偏好，是平台的一条硬规定：平台只收一个 index.html，不许外链、不许后端。"
        "后面所有事——不用框架、单文件约 88.5 KB（88521 字节）、存档放本地——都是从这一条推出来的。",
    )
    k.table(
        doc,
        ["层", "你在哪儿遇到它", "里面装什么", "改它要动哪儿"],
        [
            [
                "① 界面层",
                "按钮、六维条、事件弹窗、四个页签（本周 / 赛程 / 生涯 / 收支）",
                "拼出来的 HTML 和一份样式表。它只把状态画出来，自己不做判定、不存数字",
                "src/ui/main.ts、src/ui/style.css",
            ],
            [
                "② 规则层",
                "你点「训练」之后发生的事：体力减多少、哪一维加几点",
                "一组纯函数：输入旧状态和一个动作，输出新状态和一条日志。**唯一会改数字的地方**",
                "src/core/*.ts（10 个文件）",
            ],
            [
                "③ 数据层",
                "事件文本、商店价格、八个赛季的队伍名单，以及你的存档",
                "常量表（数值 / 事件 / 名单 / 文案）+ 一个存档对象 GameState",
                "src/config.ts、src/data/*.ts、浏览器的 localStorage",
            ],
        ],
        [1.8, 4.6, 5.6, 4.0],
        size=8.5,
        caption="表 1-1　三层分工：界面不改数字，规则不画界面，数据不带判断",
    )
    k.para(
        doc,
        "**为什么要分三层**：如果界面自己也能改数字，同一个「训练」就有两处各写一遍，"
        "改一处忘一处，数值立刻分叉。现在的顺序只有一个方向：界面发一个动作 → 规则算出新状态 → "
        "界面整块重画 → 存一次档。查问题时能顺着这条线走，不用猜是哪儿改的。",
    )

    # ---------------- 二 ----------------
    k.h1(doc, "二", "三个必须懂的概念")
    k.para(
        doc,
        "只讲你能用上的部分：每个概念三段——它是什么、在这个项目里它管哪件事、一个生活比喻和一句代价。",
    )

    k.h2(doc, "① TypeScript：先检查，再运行")
    k.para(
        doc,
        "它就是 JavaScript（浏览器认的编程语言）外加一道「打字时就检查」的关卡。"
        "字段名打错、把数字当文字用、少传一个参数，写的时候就会标红，不用等玩到一半才崩。",
    )
    k.para(
        doc,
        "这个项目里它只干一件事：保证那 39 个字段的名字和形状对得上——src/types.ts 就是这张清单。"
        "打包前先跑一遍检查（tsc --noEmit），过不了就不出产物。",
    )
    k.para(
        doc,
        "**生活比喻**：装修前先在图纸上标好每个插座的位置和电压。不标也能装，但装错了要砸墙。",
    )
    k.para(doc, "**代价一句**：要多写一点「类型」的字；换来的是改错时立刻知道错在哪一行。")

    k.h2(doc, "② Vite：把一堆文件压成一个文件")
    k.para(
        doc,
        "你写的是一堆分开的文件（.ts、.css），平台只收一个 index.html。Vite 是打包机："
        "把这些文件读进来，翻译成浏览器能直接跑的样子，再全部塞进一个 HTML 里。"
        "多出来的那个插件 vite-plugin-singlefile 专门负责「塞进一个文件、不留外链」这一步。",
    )
    k.para(
        doc,
        "现在打出来的产物是**一个文件、约 88.5 KB**（切片版约 89.3 KB），里面没有一行第三方代码，"
        "也没有任何外链。用户打开它不需要联网去别处取东西。",
    )
    k.para(
        doc,
        "**生活比喻**：把一整套家具拆平、装进一个箱子再寄——收件人只需要拆一个箱，不用等七家快递。",
    )
    k.para(
        doc,
        "**代价一句**：文件越大首屏越慢；线上出问题时，你面对的是一整块巨大的文件，不好定位。",
    )

    k.h2(doc, "③ localStorage：浏览器自带的小抽屉")
    k.para(
        doc,
        "浏览器给每个页面一个小抽屉，按「键」存一小段文字，关页面、关机都还在。"
        "这个游戏把整个存档转成一行文字塞进去，键名是 lpl-career-proto:v3——"
        "**版本号写在键名里**，所以存档格式一升级，旧档自然读不到，不会读到一半崩。",
    )
    k.para(
        doc,
        "读档时会先验：版本号不对、或者缺了年份和六维，就当没有存档、回开局屏，不弹错误框。"
        "写不进去（比如隐私模式 / 嵌在别人的 webview 里）也不报错，只是这一局白玩。",
    )
    k.para(
        doc,
        "**生活比喻**：便利贴贴在冰箱上——只有这台设备的这个浏览器看得见。"
        "换手机、换浏览器、清缓存，就没了。",
    )
    k.para(
        doc,
        "**代价一句**：没有云同步、不能跨设备；「换个手机接着玩」这件事现在做不到。",
    )

    # ---------------- 三 ----------------
